import json
f='fe616d40-a9c6-56d7-9da1-7168a172765d.jsonl'
lines=open(f).read().split('\n')
for n in range(7020,7436):
    if not lines[n-1].strip(): continue
    o=json.loads(lines[n-1])
    t=o.get('type'); ts=o.get('timestamp')
    m=o.get('message',{})
    if not isinstance(m,dict): continue
    c=m.get('content')
    out=[]
    if t=='user' and isinstance(c,str): out.append(c)
    elif isinstance(c,list):
        for b in c:
            if b.get('type')=='text': out.append(b['text'])
    if out and t in ('user','assistant'):
        txt='\n'.join(out)
        print(f'--- L{n} {t} {ts} len={len(txt)}'); print(txt[:300].replace('\n',' | '))
EOF

